def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"[^0-9]", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    # Each record contains its original position, timestamp, and normalized data.
    records = []
    for position, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        normalized = {
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower()
            in {"y", "yes", "true", "1"},
        }
        records.append((position, parse_updated(row["updated"]), normalized))

    # Union-find captures transitive matches.
    parent = list(range(len(records)))
    size = [1] * len(records)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left, right = find(left), find(right)
        if left == right:
            return
        if size[left] < size[right]:
            left, right = right, left
        parent[right] = left
        size[left] += size[right]

    email_owner = {}
    phone_name_owner = {}

    for index, (_, _, row) in enumerate(records):
        if row["email"]:
            key = row["email"]
            if key in email_owner:
                union(index, email_owner[key])
            else:
                email_owner[key] = index

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_name_owner:
                union(index, phone_name_owner[key])
            else:
                phone_name_owner[key] = index

    groups = {}
    for index in range(len(records)):
        groups.setdefault(find(index), []).append(index)

    output = []
    for members in sorted(groups.values(), key=lambda group: records[group[0]][0]):
        # Highest priority: manual source, newest timestamp, earliest input row.
        ranked = sorted(
            members,
            key=lambda index: (
                records[index][2]["source"] == "manual",
                records[index][1],
                -records[index][0],
            ),
            reverse=True,
        )

        person = {}
        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            person[field] = next(
                (
                    records[index][2][field]
                    for index in ranked
                    if records[index][2][field]
                ),
                "",
            )

        tags = set()
        for index in members:
            tags.update(records[index][2]["tags"])

        person["tags"] = ";".join(sorted(tags))
        person["opted_out"] = (
            "Y" if any(records[index][2]["opted_out"] for index in members) else "N"
        )
        person["updated"] = max(
            records[index][1] for index in members
        ).strftime("%Y-%m-%d")
        output.append(person)

    # Opted-out people remain in the output, marked "Y"; exclude them when sending.
    return output
